head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > E > ondateselect]<br/>Calendar 컴포넌트에서 날짜를 선택할 때 발생합니다.",
    "validation" : [
        "Calendar 컴포넌트에서 날짜를 선택할 때 ondateselect 이벤트가 발생합니다.",
        "date 파라미터로 setDateFormat() 메소드로 지정한 포맷에 맞게 선택일이 전달됩니다.",
        "dateObject 파라미터로 선택한 날짜의 Date 객체가 전달됩니다. (Date 객체는 1970년 1월 1일(UTC) 자정으로부터 경과한 시간을 밀리초(ms) 단위의 정수로 저장)",
        "컴포넌트의 날짜를 클릭 시 발생하며, 비활성화된 날짜를 클릭 시에는 발생하지 않습니다.",
        "날짜 셀을 클릭하면 ondateselect 이벤트가 발생합니다.",
        "사용자의 조작으로 선택일이 변경되면 onchange -> ondateselect -> onviewchange 순서로 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내 (validation 4, 5)
    $c.gcm.createLabel('label="[수동 테스트 안내] (1) 활성화된 날짜 셀 클릭 시 ondateselect 이벤트 발생, (2) 비활성화된 날짜(2025-11-05) 클릭 시 ondateselect 이벤트 미발생, (3) 날짜 셀 클릭 시 onchange → ondateselect → onviewchange 순서로 이벤트 발생"', '', 'label1');

    let properties = {}

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "ondateselect", "onviewchange"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11

    // 비활성화된 날짜 설정: 2025-11-05 (validation 4 검증용)
    target1.setDisabledDate("20251105");

    // setDateFormat 적용: date 파라미터에 포맷 적용 확인 (validation 2)
    target1.setDateFormat("yyyy-MM-dd");
}



// 선택된 날짜가 변경될 때 발생 (validation 6: 이벤트 순서 검증)
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생]");
};



// Calendar 컴포넌트에서 날짜를 선택할 때 발생 (validation 1, 2, 3, 4, 5)
scwin.target1_ondateselect = function (date, dateObject) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ondateselect=====");
    wf_body_bottom.getObj("scwin").setReturnValue("date : " + date);
    wf_body_bottom.getObj("scwin").setReturnValue("dateObject : " + dateObject);
    wf_body_bottom.getObj("scwin").setReturnValue("dateObject instanceof Date : " + (dateObject instanceof Date));
};



// 사용자의 조작에 의해 선택일이 변경된 경우 발생 (validation 6: 이벤트 순서 검증)
scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onviewchange 발생]");
};
